function shipButton(item){return button('確認交付此批次','ship',`data-item="${item}" ${e.near(e.w.actors.player,INFRA[1].port)?'':'disabled'}`,'full primary');}
function workerPanel(){const w=e.w,a=w.actors.worker;if(!a)return `<p class="muted">首單完成後可聘用一名搬運工。他會實際走到來源取晶圓，再送到下一站；你繼續負責耗材、工具、開工與出貨。</p>${commandButton('聘用搬運工 · 200 C',{type:'hire'})}<p class="muted">${!w.shippedCount?'尚未解鎖：完成教學訂單。':'投資後保留至少 100 C 營運金。'}</p>`;
 const t=w.tasks[a.task];let h=`<span class="tag">${a.carried?'持有 '+itemName(w,w.items[a.carried],e.c):'空手'}</span><p class="reason">${t?esc(t.reason||({TO_SOURCE:'前往來源',TO_DESTINATION:'運往下一站',RETURNING:'實際返還材料倉',BLOCKED:'等待可用位置'}[t.state]||t.state)):w.rules.enabled?'等待可搬運晶圓與空槽':'搬運規則已停用'}</p>${commandButton(w.rules.enabled?'停用搬運規則':'啟用晶圓搬運',{type:'rule',enabled:!w.rules.enabled})}${t?commandButton('取消任務，實際返還',{type:'cancelTask'},'full'):''}${a.carried?commandButton('就近接手晶圓',{type:'handoff'},'full'):''}<div class="detail-grid"><div><small>已走距離</small><b>${a.distance.toFixed(1)} 格</b></div><div><small>載物距離 / 時間</small><b>${a.loadedDistance.toFixed(1)} 格 / ${(a.loadedTicks/60).toFixed(1)}s</b></div></div><p class="muted">目的忙碌時等待，不會先拿走晶圓。停用或取消已持物任務時，實際返還材料倉；滿倉可走近接手。</p><div class="section-label">每道工序的目的設備</div>`;
 for(const cap of ['dep','litho','etch','clean','inspect']){h+=`<label>${e.c.machines[cap].label}</label><select data-worker-target="${cap}"><option value="">自動選擇最近空槽</option>${Object.values(w.machines).filter(m=>e.c.machines[m.definitionId].capability===cap).map(m=>`<option value="${m.id}" ${w.rules.targets[cap]===m.id?'selected':''}>${m.id} · ${e.c.machines[m.definitionId].label}</option>`).join('')}</select>`;}return h;}
$('panelBody').addEventListener('change',ev=>{if(ev.target.dataset.workerTarget)doCommand({type:'target',capability:ev.target.dataset.workerTarget,machine:ev.target.value});});
$('panelBody').addEventListener('click',ev=>{const b=ev.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case 'command':doCommand(JSON.parse(b.dataset.command));break;case 'panel':openPanel(b.dataset.panel);break;case 'select':select(b.dataset.target);break;case 'go':navigate({x:+b.dataset.x,y:+b.dataset.y});break;case 'build':beginBuild(b.dataset.definition);break;case 'relocate':beginBuild(e.w.machines[b.dataset.target].definitionId,b.dataset.target);break;case 'ship':confirm('交付圖案化試片','系統會驗證完整履歷、品質與交期，合格片數結算一次收入。',()=>doCommand({type:'ship',item:b.dataset.item,confirm:true}));break;case 'abort':confirm('中止並隔離此批次','已使用的費用及材料不退回，整盒將不可交付。取出後可送材料倉報廢。',()=>doCommand({type:'abort',target:b.dataset.target,confirm:true}));break;case 'scrap':confirm('報廢手上物品','整件封存，不退還費用或已用材料。',()=>doCommand({type:'scrap',confirm:true}));break;case 'save':toast(saves.save(e)?'已保存完整世界':saves.error);break;case 'load':confirm('讀取存檔','目前未保存進度將被替換。',()=>{try{saves.apply(e,saves.load(b.dataset.which));ui.selected=null;closePanel();toast('已讀取，請按繼續遊戲');}catch(err){toast(err.message,8000);}});break;case 'export':{try{download(encode(e),`wafer-works-${new Date().toISOString().slice(0,10)}.json`);toast('已匯出完整世界與營運檢查點');}catch(err){toast(err.message);}break;}case 'import':$('importFile').click();break;case 'checkpoint':confirm('恢復最近營運檢查點','資金、晶圓、設備、訂單與時間會一起回復。之後的進度將捨棄。',()=>{if(e.checkpoint){const cp=clone(e.checkpoint);e.setWorld(cp);e.checkpoint=cp;saves.save(e);ui.selected=null;closePanel();toast('已完整恢復檢查點');}});break;case 'restart':confirm('重新開始','目前世界將被新的空工廠取代，資金回到 2,000 C。',()=>{const w=createWorld();e.setWorld(w);e.checkpoint=clone(w);saves.reset(e);ui.selected=null;ui.selectedItem=null;closePanel();renderer.follow=true;toast('已建立新工廠，按繼續開始');});break;}});
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('importFile').onchange=async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('檔案超過 5 MiB');const data=decode(await file.text(),e.c);confirm('匯入此存檔',`世界資金 ${data.current.cash} C，已出貨 ${data.current.shippedCount} 批。將替換目前世界。`,()=>{saves.apply(e,data);saves.save(e);closePanel();ui.selected=null;toast('已匯入，請按繼續遊戲');});}catch(err){toast('匯入被拒絕：'+err.message,8000);}};
function beginBuild(definition,id=null){const m=e.w.machines[id],n=['dep','litho','etch','clean','inspect'].indexOf(definition),defaultPos=[[5,5],[9,5],[13,5],[17,5],[17,10]][n]||[8,10];ui.build={definition,id,x:m?.x??defaultPos[0],y:m?.y??defaultPos[1],rotation:m?.rotation||0};closePanel();e.pause.add('build');clearInput();document.body.classList.add('building');renderer.follow=false;renderer.camera={x:12,y:9};if(innerWidth<600)renderer.scale=Math.min((renderer.width-20)/24,(renderer.height-180)/18);renderBuild();}
