function guide(){const w=e.w;let titleText,text,action,fn;if(!w.shippedCount&&!w.activeOrder){titleText='01 / 接下教學訂單';text='無期限。用同一盒晶圓完成五道製程，交付 20 片合格試片。';action='開啟訂單 →';fn=()=>openPanel('orders');}else if(Object.keys(w.machines).length<5){titleText='02 / 配置五種設備';text='自由選擇位置。操作點要連通，之後空機台可免費搬遷。';action='配置設備 →';fn=()=>openPanel('build');}else if(!Object.values(w.lots).some(l=>l.disposition==='active')&&!w.shippedCount){titleText='03 / 採購第一批材料';text='晶圓 1 盒，四種補給各 5 份；10 秒後到貨。光罩已在倉庫。';action='開啟採購 →';fn=()=>openPanel('purchase');}else if(!w.shippedCount&&Object.values(w.machines).some(m=>m.definitionId!=='inspect'&&!Object.values(m.tanks).some(n=>n>0)&&!Object.values(w.lots).some(l=>l.cursor>0))){titleText='04 / 親手補給與裝光罩';text='到材料倉拿取補給盒，走到對應機台補給；光罩裝入微影機。';action='走到材料倉 →';fn=()=>navigate(INFRA[0].port);}else if(!w.shippedCount){const l=Object.values(w.lots).find(l=>l.disposition==='active');titleText=l?`05 / ${l.cursor===5?'交付試片':STAGES[l.cursor]}`:'05 / 完成首單';text=l?.cursor===5?'將晶圓盒送到出貨站，由你確認交付。':'同一盒依序走過沉積、微影、蝕刻、清洗與檢查。每站靠近後明確開工。';action='查看批次與指引 →';fn=()=>openPanel('records');}else if(!w.actors.worker){titleText='06 / 開始分工';text='首單已完成。可聘用搬運工，保留角色操作；工人只搬晶圓，不自行開工。';action='聘用搬運工 →';fn=()=>openPanel('worker');}else{titleText='持續生產 / 優化配置';text='接普通訂單，採購下一盒晶圓。工人搬運，你負責補給、開工與交付。';action='查看訂單 →';fn=()=>openPanel('orders');}
 $('guideTitle').textContent=titleText;$('guideText').textContent=text;$('guideAction').textContent=action;$('guideAction').onclick=fn;
}
function update(){if(e.lastError&&ui.errorShown!==e.lastError){toast(e.lastError.message);ui.errorShown=e.lastError;}const w=e.w,mt=metrics(w);$('cash').innerHTML=w.cash.toLocaleString()+' <em>C</em>';$('output').textContent=mt.rate===null?`${mt.good} 片 / ${Math.floor(mt.observedSeconds)}s`:`${mt.rate.toFixed(1)} 片/分`;$('yield').textContent=mt.yield===null?'—':(mt.yield*100).toFixed(0)+'%';const o=w.orders[w.activeOrder];$('deadline').textContent=o?o.dueTick===null?'無期限':`${Math.ceil((o.dueTick-w.tick)/60)}s`:w.shippedCount?'待接單':'未接單';$('clock').textContent=`${String(Math.floor(w.tick/3600)).padStart(2,'0')}:${String(Math.floor(w.tick/60)%60).padStart(2,'0')}`;$('saveStatus').textContent=saves.error?'未保存':saves.lastTick!==null?'已保存':'待保存';$('pauseOverlay').hidden=!(e.pause.has('manual')||e.pause.has('hidden'))||ui.panel==='save'||!!ui.build;$('pauseBtn').innerHTML=e.pause.has('manual')||e.pause.has('hidden')?'▶ <span>繼續</span>':'Ⅱ <span>暫停</span>';context();guide();}
document.addEventListener('keydown',ev=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const k=ev.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))ev.preventDefault();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k))keys.add(k);if(ev.repeat)return;if(k==='e')ui.primaryAction?.();if(k==='q')$('cycle').click();if(k==='r'&&ui.build){ui.build.rotation=(ui.build.rotation+1)%4;renderBuild();}if(k==='escape'){if(!$('modal').hidden)closeModal();else if(ui.build)cancelBuild();else closePanel();}if(k===' '&&!ui.build)togglePause();});
document.addEventListener('keyup',ev=>keys.delete(ev.key.toLowerCase()));window.addEventListener('blur',clearInput);
