window.addEventListener('pagehide',()=>saves.save(e));
let joyId=null;const stick=$('joystick');function joy(ev){const r=stick.getBoundingClientRect(),dx=ev.clientX-r.left-r.width/2,dy=ev.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),d=Math.max(1,len/28);joystick={x:len<6?0:dx/d/28,y:len<6?0:dy/d/28};stick.querySelector('i').style.transform=`translate(${dx/d}px,${dy/d}px)`;}
stick.addEventListener('pointerdown',ev=>{ev.preventDefault();joyId=ev.pointerId;stick.setPointerCapture(joyId);joy(ev);renderer.follow=true;});stick.addEventListener('pointermove',ev=>{if(ev.pointerId===joyId)joy(ev);});const releaseJoy=ev=>{if(ev.pointerId===joyId){joyId=null;joystick={x:0,y:0};stick.querySelector('i').style.transform='';}};stick.addEventListener('pointerup',releaseJoy);stick.addEventListener('pointercancel',releaseJoy);
let drag=null;const canvas=$('factory');canvas.addEventListener('pointerdown',ev=>{const r=canvas.getBoundingClientRect();drag={id:ev.pointerId,x:ev.clientX,y:ev.clientY,localX:ev.clientX-r.left,localY:ev.clientY-r.top,camera:{...renderer.camera},moved:false};canvas.setPointerCapture(ev.pointerId);});canvas.addEventListener('pointermove',ev=>{if(!drag||drag.id!==ev.pointerId)return;let dx=ev.clientX-drag.x,dy=ev.clientY-drag.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(drag.moved){renderer.follow=false;renderer.camera={x:drag.camera.x-dx/renderer.scale,y:drag.camera.y-dy/renderer.scale};}});
canvas.addEventListener('pointerup',ev=>{if(!drag||drag.id!==ev.pointerId)return;const d=drag;drag=null;if(d.moved)return;const pt=renderer.world(d.localX,d.localY);if(ui.build){ui.build.x=Math.floor(pt.x);ui.build.y=Math.floor(pt.y);renderBuild();return;}const w=e.w;const actor=w.actors.worker;if(actor&&distance(pt,actor)<.5){select('worker');return;}const item=Object.values(w.items).find(i=>i.location.type==='ground'&&distance(i.location,pt)<.5);if(item){select(item.id);return;}const object=[...INFRA,...Object.values(w.machines).map(m=>({...m,w:2,h:2}))].find(o=>(pt.x>=o.x&&pt.x<=o.x+o.w&&pt.y>=o.y&&pt.y<=o.y+o.h)||distance(pt,o.port||port(o))<.4);if(object){select(object.id);return;}navigate({x:Math.floor(pt.x)+.5,y:Math.floor(pt.y)+.5});});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('wheel',ev=>{ev.preventDefault();renderer.scale=Math.max(10,Math.min(80,renderer.scale*(ev.deltaY>0?.93:1.07)));},{passive:false});
const qaMode=new URLSearchParams(location.search).has('qa');
let qaNode=null;if(qaMode){qaNode=document.createElement('script');qaNode.type='application/json';qaNode.id='qa-state';document.body.append(qaNode);}
function simulationFrame(){const now=performance.now();if(!lastFrame)lastFrame=now;const dt=Math.min((now-lastFrame)/1000,5/60);lastFrame=now;if(e.pause.size)accumulator=0;else accumulator+=dt;let steps=0;while(accumulator>=1/60&&steps<5){let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x,y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y;e.tick({x,y});accumulator-=1/60;steps++;if(e.w.tick%600===0)savePending=true;}if(savePending){saves.save(e);savePending=false;}if(++frame%8===0){update();if(qaNode)qaNode.textContent=JSON.stringify({world:e.w,pause:[...e.pause],view:{width:renderer.width,height:renderer.height,scale:renderer.scale,camera:renderer.camera}});}if(ui.panel&&now-lastPanel>500){renderPanel();lastPanel=now;}if(now>toastUntil)$('toast').hidden=true;}
setInterval(simulationFrame,1000/60);
function animate(){renderer.draw(e,ui);requestAnimationFrame(animate);}
if(new URLSearchParams(location.search).has('qa'))Object.defineProperty(window,'waferRead',{value:Object.freeze({snapshot:()=>clone(e.w),screen:p=>renderer.screen(p),pause:()=>[...e.pause],validate:()=>validateWorld(e.w),view:()=>({width:renderer.width,height:renderer.height,scale:renderer.scale,camera:{...renderer.camera}})})});
update();requestAnimationFrame(animate);
